export const code = async (inputs) => {
  return {
    to: inputs.webhook_body.to,
    body: inputs.webhook_body.body,
    lead_id: inputs.webhook_body.lead_id,
    step_id: inputs.webhook_body.step_id
  };
};

export const code = async (inputs) => {
  const optOutKeywords = ['STOP', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT'];
  const bodyUpper = inputs.body.toUpperCase();

  for (const keyword of optOutKeywords) {
    if (bodyUpper.includes(keyword)) {
      return { opted_out: true, keyword: keyword };
    }
  }

  return { opted_out: false };
};

export const code = async (inputs) => {
  let message = inputs.body;

  // Append opt-out instruction if not already present
  if (!message.toLowerCase().includes('stop') && !message.toLowerCase().includes('reply')) {
    message += '\n\nReply STOP to opt out.';
  }

  return { message: message };
};

export const code = async (inputs) => {
  // Log to Prometheus pushgateway
  const metric = {
    job: 'campaign_engine',
    instance: 'activepieces',
    labels: {
      channel: 'sms',
      step_id: inputs.step_id,
      lead_id: inputs.lead_id,
      status: inputs.success ? 'sent' : 'failed'
    },
    value: 1,
    timestamp: Date.now()
  };

  // In production, push to Prometheus pushgateway
  console.log('SMS Metric:', metric);

  return metric;
};

